     ],
     'out' => [
       ['en' => 'Recommended MCB', 'gu' => 'ભલામણ કરેલ MCB', 'f' => '((d) => (d <= 6 ? "6 A" : d <= 10 ? "10 A" : d <= 16 ? "16 A" : d <= 20 ? "20 A" : d <= 25 ? "25 A" : d <= 32 ? "32 A" : d <= 40 ? "40 A" : d <= 50 ? "50 A" : d <= 63 ? "63 A" : T("63 A થી વધુ – MCCB વાપરો", "Above 63 A – use MCCB")) + " " + (v.type == 1 ? "B" : v.type == 2 ? "C" : "D") + T(" કર્વ", " curve"))(v.watt / ((v.ph == 3 ? sqrt(3) : 1) * v.volt * v.pf) * 1.25)', 'fmt' => 'text', 'big' => 1],
       ['en' => 'Load current', 'gu' => 'લોડ કરંટ', 'f' => 'v.volt && v.pf ? v.watt / ((v.ph == 3 ? sqrt(3) : 1) * v.volt * v.pf) : 0', 'fmt' => 'num', 'u' => 'A'],
       ['en' => 'Design current (× 1.25)', 'gu' => 'ડિઝાઇન કરંટ (× 1.25)', 'f' => 'v.volt && v.pf ? v.watt / ((v.ph == 3 ? sqrt(3) : 1) * v.volt * v.pf) * 1.25 : 0', 'fmt' => 'num', 'u' => 'A'],
     ],
     'how_en' => 'Current I = W ÷ (V × PF) for single phase or W ÷ (√3 × V × PF) for three phase. MCB = next standard size (6, 10, 16, 20, 25, 32, 40, 50, 63 A) above I × 1.25. B curve for resistive loads, C for motors/ACs, D for very high inrush loads.',
     'how_gu' => 'કરંટ I = W ÷ (V × PF) સિંગલ ફેઝ માટે, અથવા W ÷ (√3 × V × PF) થ્રી ફેઝ માટે. MCB = I × 1.25 થી ઉપરની પ્રમાણભૂત સાઇઝ (6, 10, 16, 20, 25, 32, 40, 50, 63 A). રેઝિસ્ટિવ લોડ માટે B, મોટર/AC માટે C, ખૂબ વધારે શરૂઆતી કરંટ માટે D કર્વ.',
     'faq' => [['Can the MCB be bigger than the wire rating?', 'No. The MCB must protect the wire, so its rating should not be more than the current capacity of the wire it feeds.', 'શું MCB વાયરની ક્ષમતાથી મોટું હોઈ શકે?', 'ના. MCB વાયરને બચાવવા માટે છે, તેથી તેનું રેટિંગ તે વાયરની કરંટ ક્ષમતાથી વધારે ન હોવું જોઈએ.']]],

    ['slug' => 'house-wiring-voltage-drop-calculator', 'cat' => 'electrician', 'type' => 'calc', 'icon' => 'trending-down',
     'en' => 'Voltage Drop Calculator for House Wiring', 'gu' => 'ઘર વાયરિંગ માટે વોલ્ટેજ ડ્રોપ કેલ્ક્યુલેટર',
     'de' => 'Check voltage drop on a 230 V or 415 V wiring run for a given length, current and wire size, and see if it is within limits.',
