       $MAT, $PH,
       ['k' => 'volt', 'en' => 'Supply voltage', 'gu' => 'સપ્લાય વોલ્ટેજ', 'v' => 230, 'u' => 'V'],
     ],
     'out' => [
       ['en' => 'Voltage drop', 'gu' => 'વોલ્ટેજ ડ્રોપ', 'f' => '(v.ph == 3 ? sqrt(3) : 2) * v.len * v.amp * (v.mat == 1 ? 0.0206 : 0.0339) / v.size', 'fmt' => 'num', 'u' => 'V', 'big' => 1],
       ['en' => 'Voltage drop %', 'gu' => 'વોલ્ટેજ ડ્રોપ %', 'f' => 'v.volt ? (v.ph == 3 ? sqrt(3) : 2) * v.len * v.amp * (v.mat == 1 ? 0.0206 : 0.0339) / v.size / v.volt * 100 : 0', 'fmt' => 'pct'],
       ['en' => 'Voltage at load', 'gu' => 'લોડ પર વોલ્ટેજ', 'f' => 'v.volt - (v.ph == 3 ? sqrt(3) : 2) * v.len * v.amp * (v.mat == 1 ? 0.0206 : 0.0339) / v.size', 'fmt' => 'num', 'd' => 1, 'u' => 'V'],
       ['en' => 'Status', 'gu' => 'સ્થિતિ', 'f' => '((p) => p <= 3 ? T("બરાબર – લાઇટ અને પાવર બંને માટે", "OK for lighting and power") : p <= 5 ? T("પાવર સર્કિટ માટે ચાલે, લાઇટ માટે વધારે", "OK for power circuits, high for lighting") : T("વધારે – મોટો વાયર લો", "Too high – use a bigger wire"))(v.volt ? (v.ph == 3 ? sqrt(3) : 2) * v.len * v.amp * (v.mat == 1 ? 0.0206 : 0.0339) / v.size / v.volt * 100 : 0)', 'fmt' => 'text'],
     ],
     'how_en' => 'Single phase drop = 2 × L × I × ρ ÷ A (both conductors). Three phase drop = √3 × L × I × ρ ÷ A. ρ at about 70 °C: copper 0.0206, aluminium 0.0339 Ω·mm²/m. Keep drop within about 3% for lighting and 5% for power.',
     'how_gu' => 'સિંગલ ફેઝ ડ્રોપ = 2 × L × I × ρ ÷ A (બંને વાયર). થ્રી ફેઝ ડ્રોપ = √3 × L × I × ρ ÷ A. લગભગ 70 °C પર ρ: કોપર 0.0206, એલ્યુમિનિયમ 0.0339 Ω·mm²/m. લાઇટ માટે ડ્રોપ 3% અને પાવર માટે 5% અંદર રાખો.',
     'faq' => [['Why does voltage drop matter?', 'High drop makes motors and ACs run hot, lights dim and stabilisers work harder. On long runs to a pump or outhouse, a bigger wire saves trouble.', 'વોલ્ટેજ ડ્રોપ કેમ મહત્વનું છે?', 'વધારે ડ્રોપથી મોટર અને AC ગરમ થાય, લાઇટ ઝાંખી થાય અને સ્ટેબિલાઇઝર પર ભાર વધે. પંપ કે દૂરના રૂમ સુધીની લાંબી લાઇનમાં મોટો વાયર મુશ્કેલી બચાવે.']]],

    ['slug' => 'earthing-rod-resistance-calculator', 'cat' => 'electrician', 'type' => 'calc', 'icon' => 'arrow-down-to-line',
