       ['k' => 'rho', 'en' => 'Soil resistivity', 'gu' => 'માટીની રેઝિસ્ટિવિટી', 'v' => 100, 'u' => 'Ω·m'],
       ['k' => 'len', 'en' => 'Rod length in ground', 'gu' => 'જમીનમાં રોડની લંબાઈ', 'v' => 3, 'u' => 'm', 'u_gu' => 'મીટર'],
