       ['k' => 'people', 'en' => 'People usually in room', 'gu' => 'રૂમમાં સામાન્ય રીતે લોકો', 'v' => 2],
       ['k' => 'sun', 'en' => 'Sun / heat exposure', 'gu' => 'તડકો / ગરમી', 'v' => 1.1, 'opts' => [[1, 'Shaded, lower floor', 'છાંયડો, નીચેનો માળ'], [1.1, 'Some sun on walls', 'દીવાલ પર થોડો તડકો'], [1.2, 'Top floor or west facing', 'ઉપરનો માળ કે પશ્ચિમ તરફ'], [1.35, 'Shop / kitchen / lots of glass', 'દુકાન / રસોડું / ઘણો કાચ']]],
       ['k' => 'base', 'en' => 'Base cooling load', 'gu' => 'મૂળ ઠંડક લોડ', 'v' => 80, 'u' => 'BTU/sq ft'],
