       ['en' => 'Heat load', 'gu' => 'ગરમી લોડ', 'f' => 'v.len * v.wid * v.base * (v.ht / 10) * v.sun + max(0, v.people - 2) * 600', 'fmt' => 'int', 'u' => 'BTU/hr'],
       ['en' => 'Room area', 'gu' => 'રૂમનું ક્ષેત્રફળ', 'f' => 'v.len * v.wid', 'fmt' => 'int', 'u' => 'sq ft'],
