       ['en' => 'Allowed fill', 'gu' => 'મંજૂર ભરાવો', 'f' => 'v.n == 1 ? 53 : v.n == 2 ? 31 : 40', 'fmt' => 'pct', 'd' => 0],
       ['en' => 'Max wires of this size (40%)', 'gu' => 'આ સાઇઝના વધુમાં વધુ વાયર (40%)', 'f' => 'floor(0.4 * v.id * v.id / (v.od * v.od))', 'fmt' => 'int'],
