       ['en' => 'kVA', 'gu' => 'kVA', 'f' => 'v.mode == 1 ? v.val : (v.pf ? v.val / v.pf : 0)', 'fmt' => 'num', 'd' => 3, 'u' => 'kVA'],
       ['en' => 'kVAR', 'gu' => 'kVAR', 'f' => '(v.mode == 1 ? v.val : (v.pf ? v.val / v.pf : 0)) * sqrt(max(0, 1 - v.pf * v.pf))', 'fmt' => 'num', 'd' => 3, 'u' => 'kVAR'],
