       ['en' => 'Phase angle', 'gu' => 'ફેઝ એંગલ', 'f' => '((p) => p > 0 && p <= 1 ? deg(atan(sqrt(1 - p * p) / p)) : 0)(v.volt && v.amp ? v.watt / ((v.ph == 3 ? sqrt(3) : 1) * v.volt * v.amp) : 0)', 'fmt' => 'num', 'd' => 1, 'u' => '°'],
       ['en' => 'Status', 'gu' => 'સ્થિતિ', 'f' => '((p) => p > 1 ? T("રીડિંગ ફરી તપાસો", "Check readings") : p >= 0.95 ? T("ઉત્તમ", "Excellent") : p >= 0.85 ? T("સારો", "Good") : T("ઓછો – કેપેસિટર વિચારો", "Low – consider capacitor"))(v.volt && v.amp ? v.watt / ((v.ph == 3 ? sqrt(3) : 1) * v.volt * v.amp) : 0)', 'fmt' => 'text'],
     ],
     'how_en' => 'Power factor = real power (W) ÷ apparent power (VA). VA = V × I for single phase, √3 × V(line) × I for three phase. Phase angle φ = arccos(PF).',
