       ['en' => 'Calculated power', 'gu' => 'ગણેલો પાવર', 'f' => 'v.eff ? 9.81 * (v.lpm / 60000) * v.head / (v.eff / 100) / 0.746 : 0', 'fmt' => 'num', 'u' => 'HP'],
       ['en' => 'Motor input power', 'gu' => 'મોટર ઇનપુટ પાવર', 'f' => 'v.eff ? 9.81 * (v.lpm / 60000) * v.head / (v.eff / 100) : 0', 'fmt' => 'num', 'u' => 'kW'],
       ['en' => 'Water per hour', 'gu' => 'કલાક દીઠ પાણી', 'f' => 'v.lpm * 60', 'fmt' => 'int', 'u' => 'litres', 'u_gu' => 'લિટર'],
