       ['en' => 'Status', 'gu' => 'સ્થિતિ', 'f' => '((u) => u <= 10 ? T("સંતુલિત", "Balanced") : u <= 20 ? T("થોડું અસંતુલન – લોડ ફેરવો", "Some unbalance – shift a few loads") : T("વધારે અસંતુલન – સૌથી વધુ લોડવાળા ફેઝમાંથી લોડ ખસેડો", "High unbalance – move load off the heaviest phase"))(((a) => a ? max(abs(v.r - a), abs(v.y - a), abs(v.b - a)) / a * 100 : 0)((v.r + v.y + v.b) / 3))', 'fmt' => 'text'],
