       ['en' => 'Owner / main share', 'gu' => 'માલિક / મુખ્યનો ભાગ', 'f' => 'v.total ? (v.bill - v.fixed) * (v.total - v.sub) / v.total + v.fixed / 2 : 0', 'fmt' => 'inr'],
       ['en' => 'Effective rate per unit', 'gu' => 'યુનિટ દીઠ અસરકારક દર', 'f' => 'v.total ? (v.bill - v.fixed) / v.total : 0', 'fmt' => 'inr'],
