    ['slug' => 'cctv-12v-dc-voltage-drop-calculator', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'trending-down',
     'en' => 'CCTV 12V DC Cable Voltage Drop Calculator', 'gu' => 'CCTV 12V DC કેબલ વોલ્ટેજ ડ્રોપ કેલ્ક્યુલેટર',
     'de' => 'Check the 12 V reaching a CCTV camera over a 3+1 or power cable run and the maximum cable length before night vision fails.',
     'dg' => '3+1 કે પાવર કેબલથી CCTV કેમેરા સુધી કેટલા 12 V પહોંચે છે અને નાઇટ વિઝન બગડે તે પહેલાં વધુમાં વધુ કેટલી કેબલ લંબાઈ ચાલે તે તપાસો.',
     'in' => [
       ['k' => 'len', 'en' => 'Cable length (one way)', 'gu' => 'કેબલ લંબાઈ (એક તરફ)', 'v' => 60, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['k' => 'amp', 'en' => 'Camera current', 'gu' => 'કેમેરાનો કરંટ', 'v' => 0.5, 'u' => 'A'],
       ['k' => 'size', 'en' => 'Power core size', 'gu' => 'પાવર કોરની સાઇઝ', 'v' => 0.5, 'opts' => [[0.35, '0.35 sq mm', '0.35 sq mm'], [0.5, '0.5 sq mm (3+1 cable)', '0.5 sq mm (3+1 કેબલ)'], [0.75, '0.75 sq mm', '0.75 sq mm'], [1, '1 sq mm', '1 sq mm'], [1.5, '1.5 sq mm', '1.5 sq mm']]],
       ['k' => 'rho', 'en' => 'Conductor', 'gu' => 'વાયરની ધાતુ', 'v' => 0.0175, 'opts' => [[0.0175, 'Pure copper', 'શુદ્ધ કોપર'], [0.028, 'CCA (copper-clad aluminium)', 'CCA (કોપર-ક્લેડ એલ્યુમિનિયમ)']]],
       ['k' => 'vs', 'en' => 'SMPS output voltage', 'gu' => 'SMPS આઉટપુટ વોલ્ટેજ', 'v' => 12, 'u' => 'V'],
     ],
     'out' => [
       ['en' => 'Voltage at camera', 'gu' => 'કેમેરા પર વોલ્ટેજ', 'f' => 'v.vs - 2 * v.len * v.amp * v.rho / v.size', 'fmt' => 'num', 'u' => 'V', 'big' => 1],
       ['en' => 'Voltage drop', 'gu' => 'વોલ્ટેજ ડ્રોપ', 'f' => '2 * v.len * v.amp * v.rho / v.size', 'fmt' => 'num', 'u' => 'V'],
       ['en' => 'Max length for 10% drop', 'gu' => '10% ડ્રોપ માટે વધુમાં વધુ લંબાઈ', 'f' => 'v.amp ? 0.1 * v.vs * v.size / (2 * v.amp * v.rho) : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['en' => 'Status', 'gu' => 'સ્થિતિ', 'f' => 'v.vs - 2 * v.len * v.amp * v.rho / v.size >= v.vs * 0.9 ? T("બરાબર", "OK") : T("વોલ્ટેજ ઓછો – SMPS કેમેરા પાસે મૂકો કે જાડો વાયર લો", "Too low – move SMPS closer or use thicker wire")', 'fmt' => 'text'],
     ],
     'how_en' => 'Drop = 2 × length × current × resistivity ÷ wire area (current flows out and back). Resistivity: copper 0.0175, CCA about 0.028 Ω·mm²/m. Most 12 V cameras need at least 10.8 V (−10%), or IR and video become unstable at night.',
     'how_gu' => 'ડ્રોપ = 2 × લંબાઈ × કરંટ × રેઝિસ્ટિવિટી ÷ વાયર ક્ષેત્રફળ (કરંટ જાય અને પાછો આવે). રેઝિસ્ટિવિટી: કોપર 0.0175, CCA લગભગ 0.028 Ω·mm²/m. મોટા ભાગના 12 V કેમેરાને ઓછામાં ઓછા 10.8 V (−10%) જોઈએ, નહીં તો રાત્રે IR અને વીડિયો અસ્થિર થાય.'],

