       ['k' => 'setup', 'en' => 'DVR/NVR setup & mobile app', 'gu' => 'DVR/NVR સેટઅપ અને મોબાઇલ એપ', 'v' => 800, 'u' => '₹'],
       ['k' => 'height', 'en' => 'Ladder / height work extra', 'gu' => 'સીડી / ઊંચાઈ કામ વધારાનું', 'v' => 0, 'u' => '₹'],
