    ['slug' => 'cloud-vs-local-cctv-storage-cost', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'cloud',
     'en' => 'Cloud vs Local CCTV Recording Cost Comparison', 'gu' => 'ક્લાઉડ સામે લોકલ CCTV રેકોર્ડિંગ ખર્ચ સરખામણી',
     'de' => 'Compare the total cost of cloud CCTV recording plans with a local NVR/DVR and hard disk over the years, including electricity.',
     'dg' => 'વર્ષો દરમિયાન ક્લાઉડ CCTV રેકોર્ડિંગ પ્લાન અને લોકલ NVR/DVR + હાર્ડ ડિસ્કના કુલ ખર્ચની વીજળી સાથે સરખામણી કરો.',
     'in' => [
       ['k' => 'cams', 'en' => 'Cameras', 'gu' => 'કેમેરા', 'v' => 4],
       ['k' => 'cloud', 'en' => 'Cloud plan per camera per month', 'gu' => 'કેમેરા દીઠ માસિક ક્લાઉડ પ્લાન', 'v' => 200, 'u' => '₹'],
       ['k' => 'years', 'en' => 'Period', 'gu' => 'સમયગાળો', 'v' => 3, 'u' => 'years', 'u_gu' => 'વર્ષ'],
       ['k' => 'local', 'en' => 'Recorder + HDD cost', 'gu' => 'રેકોર્ડર + HDD ખર્ચ', 'v' => 9000, 'u' => '₹'],
       ['k' => 'watt', 'en' => 'Recorder power', 'gu' => 'રેકોર્ડરનો પાવર', 'v' => 20, 'u' => 'W'],
       ['k' => 'rate', 'en' => 'Electricity rate', 'gu' => 'વીજ દર', 'v' => 7, 'u' => '₹/unit', 'u_gu' => '₹/યુનિટ'],
     ],
     'out' => [
       ['en' => 'Cheaper option', 'gu' => 'સસ્તો વિકલ્પ', 'f' => 'v.cams * v.cloud * 12 * v.years < v.local + v.watt * 24 * 365 / 1000 * v.rate * v.years ? T("ક્લાઉડ", "Cloud") : T("લોકલ રેકોર્ડર", "Local recorder")', 'fmt' => 'text', 'big' => 1],
       ['en' => 'Cloud total', 'gu' => 'ક્લાઉડ કુલ ખર્ચ', 'f' => 'v.cams * v.cloud * 12 * v.years', 'fmt' => 'inr'],
       ['en' => 'Local total (incl. electricity)', 'gu' => 'લોકલ કુલ ખર્ચ (વીજળી સાથે)', 'f' => 'v.local + v.watt * 24 * 365 / 1000 * v.rate * v.years', 'fmt' => 'inr'],
       ['en' => 'Difference', 'gu' => 'તફાવત', 'f' => 'abs(v.cams * v.cloud * 12 * v.years - (v.local + v.watt * 24 * 365 / 1000 * v.rate * v.years))', 'fmt' => 'inr'],
       ['en' => 'Months for local to become cheaper', 'gu' => 'લોકલ સસ્તું થવાના મહિના', 'f' => '(v.cams * v.cloud - v.watt * 24 * 30 / 1000 * v.rate) > 0 ? v.local / (v.cams * v.cloud - v.watt * 24 * 30 / 1000 * v.rate) : 0', 'fmt' => 'num', 'd' => 1, 'u' => 'months', 'u_gu' => 'મહિના'],
     ],
     'how_en' => 'Cloud total = cameras × monthly plan × 12 × years. Local total = recorder and HDD cost + recorder watts × 24 × 365 ÷ 1000 × rate × years. Break-even months = local cost ÷ (monthly cloud fee − monthly electricity).',
     'how_gu' => 'ક્લાઉડ કુલ = કેમેરા × માસિક પ્લાન × 12 × વર્ષ. લોકલ કુલ = રેકોર્ડર અને HDD ખર્ચ + રેકોર્ડર વોટ × 24 × 365 ÷ 1000 × દર × વર્ષ. બ્રેક-ઇવન મહિના = લોકલ ખર્ચ ÷ (માસિક ક્લાઉડ ફી − માસિક વીજળી).',
     'faq' => [['Which is safer?', 'Cloud keeps footage even if a thief takes away the recorder, but needs steady internet upload. Many shops use local recording plus cloud backup of one or two key cameras.', 'કયું વધુ સુરક્ષિત?', 'ચોર રેકોર્ડર લઈ જાય તો પણ ક્લાઉડમાં ફૂટેજ રહે, પણ સતત ઇન્ટરનેટ અપલોડ જોઈએ. ઘણી દુકાનો લોકલ રેકોર્ડિંગ અને એક-બે મુખ્ય કેમેરાનું ક્લાઉડ બેકઅપ રાખે છે.']]],

    ['slug' => 'ptz-camera-zoom-distance-calculator', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'zoom-in',
     'en' => 'PTZ Camera Zoom Distance Calculator', 'gu' => 'PTZ કેમેરા ઝૂમ અંતર કેલ્ક્યુલેટર',
     'de' => 'Find how far a PTZ camera can identify, recognise or detect a person at full optical zoom, from focal length, sensor and resolution.',
     'dg' => 'ફોકલ લેન્થ, સેન્સર અને રિઝોલ્યુશન પરથી PTZ કેમેરા પૂરા ઓપ્ટિકલ ઝૂમે કેટલા અંતર સુધી વ્યક્તિને ઓળખી, પારખી કે જોઈ શકે તે શોધો.',
     'in' => [
       ['k' => 'f', 'en' => 'Minimum focal length', 'gu' => 'ઓછામાં ઓછી ફોકલ લેન્થ', 'v' => 4.8, 'u' => 'mm'],
       ['k' => 'zoom', 'en' => 'Optical zoom', 'gu' => 'ઓપ્ટિકલ ઝૂમ', 'v' => 25, 'u' => '×'],
       ['k' => 'sw', 'en' => 'Sensor size', 'gu' => 'સેન્સર સાઇઝ', 'v' => 5.37, 'opts' => [[4.8, '1/3" (4.8 mm wide)', '1/3" (4.8 mm પહોળું)'], [5.37, '1/2.7" / 1/2.8" (≈5.4 mm)', '1/2.7" / 1/2.8" (≈5.4 mm)'], [5.76, '1/2.5" (5.76 mm)', '1/2.5" (5.76 mm)'], [7.18, '1/1.8" (7.18 mm)', '1/1.8" (7.18 mm)']]],
       ['k' => 'px', 'en' => 'Resolution', 'gu' => 'રિઝોલ્યુશન', 'v' => 1920, 'opts' => [[1920, '2 MP (1920 px wide)', '2 MP (1920 px)'], [2560, '4 MP (2560 px wide)', '4 MP (2560 px)'], [2880, '5 MP (2880 px wide)', '5 MP (2880 px)'], [3840, '8 MP / 4K (3840 px wide)', '8 MP / 4K (3840 px)']]],
     ],
     'out' => [
       ['en' => 'Identify a face up to', 'gu' => 'ચહેરો ઓળખી શકાય', 'f' => 'v.sw ? v.px * v.f * v.zoom / (v.sw * 250) : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'm', 'u_gu' => 'મીટર', 'big' => 1],
       ['en' => 'Recognise a known person up to', 'gu' => 'જાણીતી વ્યક્તિ પારખી શકાય', 'f' => 'v.sw ? v.px * v.f * v.zoom / (v.sw * 125) : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['en' => 'Detect a person up to', 'gu' => 'વ્યક્તિ દેખાય', 'f' => 'v.sw ? v.px * v.f * v.zoom / (v.sw * 25) : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['en' => 'Maximum focal length', 'gu' => 'મહત્તમ ફોકલ લેન્થ', 'f' => 'v.f * v.zoom', 'fmt' => 'num', 'd' => 1, 'u' => 'mm'],
       ['en' => 'View angle wide / tele', 'gu' => 'દ્રશ્ય કોણ વાઇડ / ટેલી', 'f' => 'v.f ? round(deg(2 * atan(v.sw / (2 * v.f))), 1) + "° / " + round(deg(2 * atan(v.sw / (2 * v.f * max(v.zoom, 1)))), 1) + "°" : "-"', 'fmt' => 'text'],
     ],
     'how_en' => 'Scene width at distance D = D × sensor width ÷ focal length, so D = pixels × focal length ÷ (sensor width × pixels-per-metre). Standard levels (EN 62676-4): identify 250 px/m, recognise 125 px/m, detect 25 px/m. Real range also depends on light, lens quality and weather.',
     'how_gu' => 'અંતર D પર દ્રશ્યની પહોળાઈ = D × સેન્સર પહોળાઈ ÷ ફોકલ લેન્થ, તેથી D = પિક્સેલ × ફોકલ લેન્થ ÷ (સેન્સર પહોળાઈ × પિક્સેલ પ્રતિ મીટર). પ્રમાણભૂત સ્તર (EN 62676-4): ઓળખ 250 px/m, પારખ 125 px/m, દેખાવું 25 px/m. સાચી રેન્જ પ્રકાશ, લેન્સ અને હવામાન પર પણ આધાર રાખે.'],

    ['slug' => 'cctv-camera-mounting-height-angle', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'move-diagonal',
     'en' => 'CCTV Camera Mounting Height & Tilt Angle Calculator', 'gu' => 'CCTV કેમેરા લગાવવાની ઊંચાઈ અને ઝુકાવ કોણ કેલ્ક્યુલેટર',
     'de' => 'Find the downward tilt angle and real viewing distance for a camera at a given height, and check if the angle is good for capturing faces.',
     'dg' => 'આપેલી ઊંચાઈએ લગાવેલા કેમેરાનો નીચે તરફનો ઝુકાવ કોણ અને સાચું અંતર શોધો, અને ચહેરા કેદ કરવા કોણ યોગ્ય છે કે નહીં તે તપાસો.',
     'in' => [
       ['k' => 'h', 'en' => 'Camera mounting height', 'gu' => 'કેમેરાની ઊંચાઈ', 'v' => 3, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['k' => 'd', 'en' => 'Horizontal distance to target', 'gu' => 'લક્ષ્ય સુધીનું આડું અંતર', 'v' => 6, 'u' => 'm', 'u_gu' => 'મીટર'],
       ['k' => 't', 'en' => 'Target height (face ≈ 1.6 m)', 'gu' => 'લક્ષ્યની ઊંચાઈ (ચહેરો ≈ 1.6 m)', 'v' => 1.6, 'u' => 'm', 'u_gu' => 'મીટર'],
     ],
     'out' => [
       ['en' => 'Downward tilt angle', 'gu' => 'નીચે તરફનો ઝુકાવ', 'f' => 'v.d > 0 ? deg(atan((v.h - v.t) / v.d)) : 90', 'fmt' => 'num', 'd' => 1, 'u' => '°', 'big' => 1],
       ['en' => 'Actual distance camera → face', 'gu' => 'કેમેરાથી ચહેરા સુધીનું સાચું અંતર', 'f' => 'sqrt(v.d * v.d + (v.h - v.t) * (v.h - v.t))', 'fmt' => 'num', 'u' => 'm', 'u_gu' => 'મીટર'],
       ['en' => 'Face capture', 'gu' => 'ચહેરો કેદ થશે?', 'f' => '((a) => a <= 15 ? T("ઉત્તમ – ચહેરો સીધો દેખાશે", "Excellent – faces seen straight on") : a <= 30 ? T("ચાલે – થોડો ઉપરથી દેખાશે", "Acceptable – slightly from above") : T("વધારે ઢાળ – ટોપી/માથું જ દેખાશે, કેમેરો નીચો કે દૂર લગાવો", "Too steep – mostly tops of heads; mount lower or farther"))(v.d > 0 ? deg(atan((v.h - v.t) / v.d)) : 90)', 'fmt' => 'text'],
       ['en' => 'Min. distance for a 15° angle', 'gu' => '15° કોણ માટે ઓછામાં ઓછું અંતર', 'f' => 'max(0, v.h - v.t) / tan(rad(15))', 'fmt' => 'num', 'u' => 'm', 'u_gu' => 'મીટર'],
     ],
     'how_en' => 'Tilt angle = arctan((camera height − target height) ÷ horizontal distance). Slant distance = √(distance² + height difference²). For faces, keep the vertical angle under about 15–30°.',
     'how_gu' => 'ઝુકાવ કોણ = arctan((કેમેરાની ઊંચાઈ − લક્ષ્યની ઊંચાઈ) ÷ આડું અંતર). ત્રાંસું અંતર = √(અંતર² + ઊંચાઈનો ફરક²). ચહેરા માટે ઊભો કોણ લગભગ 15–30° થી ઓછો રાખો.'],

    ['slug' => 'cctv-network-switch-port-planner', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'network',
     'en' => 'CCTV Network Switch Port Planner', 'gu' => 'CCTV નેટવર્ક સ્વિચ પોર્ટ પ્લાનર',
     'de' => 'Count the switch ports and PoE ports needed for IP cameras, NVR, uplink and other devices, and pick an 8, 16, 24 or 48 port switch.',
     'dg' => 'IP કેમેરા, NVR, અપલિંક અને અન્ય ઉપકરણ માટે કેટલા સ્વિચ પોર્ટ અને PoE પોર્ટ જોઈએ તે ગણો અને 8, 16, 24 કે 48 પોર્ટ સ્વિચ પસંદ કરો.',
     'in' => [
       ['k' => 'cams', 'en' => 'IP cameras', 'gu' => 'IP કેમેરા', 'v' => 10],
       ['k' => 'nvr', 'en' => 'NVRs', 'gu' => 'NVR', 'v' => 1],
       ['k' => 'other', 'en' => 'Other devices (PC, Wi-Fi AP)', 'gu' => 'અન્ય ઉપકરણ (PC, Wi-Fi AP)', 'v' => 2],
       ['k' => 'up', 'en' => 'Uplink to router', 'gu' => 'રાઉટર સાથે અપલિંક', 'v' => 1],
       ['k' => 'spare', 'en' => 'Spare ports', 'gu' => 'વધારાના પોર્ટ', 'v' => 20, 'u' => '%'],
     ],
     'out' => [
       ['en' => 'Switch to buy', 'gu' => 'લેવાનું સ્વિચ', 'f' => '((p) => p <= 5 ? "5" : p <= 8 ? "8" : p <= 16 ? "16" : p <= 24 ? "24" : p <= 48 ? "48" : T("48 + વધુ સ્વિચ", "48 + more switches"))(ceil((v.cams + v.nvr + v.other + v.up) * (1 + v.spare / 100))) + T(" પોર્ટ", " port")', 'fmt' => 'text', 'big' => 1],
       ['en' => 'Ports needed (with spare)', 'gu' => 'જરૂરી પોર્ટ (વધારા સાથે)', 'f' => 'ceil((v.cams + v.nvr + v.other + v.up) * (1 + v.spare / 100))', 'fmt' => 'int'],
       ['en' => 'PoE ports needed', 'gu' => 'જરૂરી PoE પોર્ટ', 'f' => 'v.cams', 'fmt' => 'int'],
       ['en' => 'Ports in use today', 'gu' => 'આજે વપરાતા પોર્ટ', 'f' => 'v.cams + v.nvr + v.other + v.up', 'fmt' => 'int'],
     ],
     'how_en' => 'Ports = (cameras + NVRs + other devices + uplinks) × (1 + spare %), rounded up, then the next standard switch size. Every IP camera needs a PoE port unless it has its own adapter.',
     'how_gu' => 'પોર્ટ = (કેમેરા + NVR + અન્ય ઉપકરણ + અપલિંક) × (1 + વધારાના %), ઉપર રાઉન્ડ, પછી ત્યાર પછીની પ્રમાણભૂત સ્વિચ સાઇઝ. દરેક IP કેમેરાને PoE પોર્ટ જોઈએ, જો અલગ એડેપ્ટર ન હોય તો.'],

    ['slug' => 'cctv-bitrate-calculator-by-resolution', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'video',
     'en' => 'CCTV Bitrate Calculator by Resolution & Codec', 'gu' => 'રિઝોલ્યુશન અને કોડેક પ્રમાણે CCTV બિટરેટ કેલ્ક્યુલેટર',
     'de' => 'Get a typical recording bitrate for 2 MP to 8 MP cameras with H.264, H.265 or smart codec, frame rate and scene type, plus daily data.',
     'dg' => '2 MP થી 8 MP કેમેરા માટે H.264, H.265 કે સ્માર્ટ કોડેક, ફ્રેમ રેટ અને દ્રશ્ય પ્રકાર પ્રમાણે સામાન્ય રેકોર્ડિંગ બિટરેટ અને રોજનો ડેટા મેળવો.',
     'in' => [
       ['k' => 'res', 'en' => 'Resolution', 'gu' => 'રિઝોલ્યુશન', 'v' => 2, 'opts' => [[2, '2 MP (1080p)', '2 MP (1080p)'], [4, '4 MP (1440p)', '4 MP (1440p)'], [5, '5 MP', '5 MP'], [8, '8 MP (4K)', '8 MP (4K)']]],
       ['k' => 'codec', 'en' => 'Codec', 'gu' => 'કોડેક', 'v' => 0.5, 'opts' => [[1, 'H.264', 'H.264'], [0.5, 'H.265', 'H.265'], [0.3, 'H.265+ / smart codec', 'H.265+ / સ્માર્ટ કોડેક']]],
       ['k' => 'fps', 'en' => 'Frame rate', 'gu' => 'ફ્રેમ રેટ', 'v' => 15, 'u' => 'fps'],
       ['k' => 'scene', 'en' => 'Scene', 'gu' => 'દ્રશ્ય', 'v' => 1, 'opts' => [[0.6, 'Low motion (store room, night corridor)', 'ઓછી હલચલ (સ્ટોર રૂમ)'], [1, 'Normal (shop, office)', 'સામાન્ય (દુકાન, ઓફિસ)'], [1.5, 'Busy (road, crowd, trees)', 'વધુ હલચલ (રસ્તો, ભીડ, ઝાડ)']]],
     ],
     'out' => [
       ['en' => 'Typical bitrate', 'gu' => 'સામાન્ય બિટરેટ', 'f' => '(v.res == 2 ? 4 : v.res == 4 ? 6 : v.res == 5 ? 8 : 12) * v.codec * v.fps / 25 * v.scene', 'fmt' => 'num', 'u' => 'Mbps', 'big' => 1],
       ['en' => 'In kbps (for recorder setting)', 'gu' => 'kbps માં (રેકોર્ડર સેટિંગ માટે)', 'f' => 'round((v.res == 2 ? 4 : v.res == 4 ? 6 : v.res == 5 ? 8 : 12) * v.codec * v.fps / 25 * v.scene * 1024 / 256) * 256', 'fmt' => 'int', 'u' => 'kbps'],
       ['en' => 'Data per camera per day', 'gu' => 'કેમેરા દીઠ રોજનો ડેટા', 'f' => '(v.res == 2 ? 4 : v.res == 4 ? 6 : v.res == 5 ? 8 : 12) * v.codec * v.fps / 25 * v.scene * 86400 / 8 / 1000', 'fmt' => 'num', 'd' => 1, 'u' => 'GB'],
     ],
     'how_en' => 'Base bitrates at 25 fps with H.264: 2 MP ≈ 4, 4 MP ≈ 6, 5 MP ≈ 8, 8 MP ≈ 12 Mbps (common recorder defaults). Bitrate = base × codec factor (H.265 ≈ 0.5, smart codec ≈ 0.3) × fps ÷ 25 × scene factor. Daily GB = Mbps × 86,400 ÷ 8 ÷ 1000.',
     'how_gu' => 'H.264 અને 25 fps પર મૂળ બિટરેટ: 2 MP ≈ 4, 4 MP ≈ 6, 5 MP ≈ 8, 8 MP ≈ 12 Mbps (સામાન્ય રેકોર્ડર ડિફોલ્ટ). બિટરેટ = મૂળ × કોડેક પરિબળ (H.265 ≈ 0.5, સ્માર્ટ ≈ 0.3) × fps ÷ 25 × દ્રશ્ય પરિબળ. રોજના GB = Mbps × 86,400 ÷ 8 ÷ 1000.',
     'faq' => [['Is this exact?', 'No — it is a typical starting value. Actual bitrate varies with camera brand, night noise and motion. Check the live bitrate shown in your recorder for a few days and adjust.', 'શું આ ચોક્કસ છે?', 'ના — આ સામાન્ય શરૂઆતી કિંમત છે. સાચો બિટરેટ કેમેરા બ્રાન્ડ, રાતનો નોઇઝ અને હલચલ પ્રમાણે બદલાય. થોડા દિવસ રેકોર્ડરમાં દેખાતો લાઇવ બિટરેટ જોઈ સુધારો.']]],

    ['slug' => '4g-cctv-camera-data-usage-calculator', 'cat' => 'cctv', 'type' => 'calc', 'icon' => 'smartphone',
     'en' => '4G SIM CCTV Camera Data Usage Calculator', 'gu' => '4G સિમ CCTV કેમેરા ડેટા વપરાશ કેલ્ક્યુલેટર',
     'de' => 'Estimate monthly mobile data used by 4G SIM CCTV cameras at farms and sites from live viewing hours and motion clip uploads.',
     'dg' => 'ખેતર અને સાઇટ પરના 4G સિમ CCTV કેમેરા લાઇવ જોવાના કલાક અને મોશન ક્લિપ અપલોડ પરથી મહિને કેટલો મોબાઇલ ડેટા વાપરે તે અંદાજો.',
     'in' => [
       ['k' => 'cams', 'en' => '4G cameras', 'gu' => '4G કેમેરા', 'v' => 1],
       ['k' => 'kbps', 'en' => 'Live view bitrate', 'gu' => 'લાઇવ વ્યૂ બિટરેટ', 'v' => 512, 'u' => 'kbps'],
       ['k' => 'hrs', 'en' => 'Live viewing per day', 'gu' => 'રોજ લાઇવ જોવાનો સમય', 'v' => 2, 'u' => 'hrs', 'u_gu' => 'કલાક'],
       ['k' => 'clips', 'en' => 'Motion clips uploaded per day', 'gu' => 'રોજ અપલોડ થતી મોશન ક્લિપ', 'v' => 200, 'u' => 'MB'],
       ['k' => 'plan', 'en' => 'Data in SIM plan per month', 'gu' => 'સિમ પ્લાનમાં માસિક ડેટા', 'v' => 30, 'u' => 'GB'],
     ],
     'out' => [
       ['en' => 'Data per month', 'gu' => 'માસિક ડેટા', 'f' => 'v.cams * (v.kbps * 3600 * v.hrs / 8 / 1e6 + v.clips / 1000) * 30', 'fmt' => 'num', 'd' => 1, 'u' => 'GB', 'big' => 1],
       ['en' => 'Data per day', 'gu' => 'રોજનો ડેટા', 'f' => 'v.cams * (v.kbps * 3600 * v.hrs / 8 / 1e6 + v.clips / 1000)', 'fmt' => 'num', 'u' => 'GB'],
       ['en' => 'Plan status', 'gu' => 'પ્લાનની સ્થિતિ', 'f' => 'v.cams * (v.kbps * 3600 * v.hrs / 8 / 1e6 + v.clips / 1000) * 30 <= v.plan ? T("પ્લાન પૂરતો છે", "Plan is enough") : T("પ્લાન ઓછો – મોટો પ્લાન કે ઓછો બિટરેટ", "Plan too small – bigger plan or lower bitrate")', 'fmt' => 'text'],
       ['en' => 'Live hours possible per day on plan', 'gu' => 'પ્લાનમાં રોજના લાઇવ કલાક શક્ય', 'f' => 'v.cams && v.kbps ? max(0, (v.plan / 30 / v.cams - v.clips / 1000) * 1e6 * 8 / (v.kbps * 3600)) : 0', 'fmt' => 'num', 'd' => 1, 'u' => 'hrs', 'u_gu' => 'કલાક'],
     ],
     'how_en' => 'Live data (GB/day) = kbps × 3600 × hours ÷ 8 ÷ 1,000,000. Add clip uploads (MB ÷ 1000). Monthly = daily × 30 × cameras. Recording to the SD card inside the camera uses no mobile data.',
     'how_gu' => 'લાઇવ ડેટા (GB/દિવસ) = kbps × 3600 × કલાક ÷ 8 ÷ 10,00,000. ક્લિપ અપલોડ (MB ÷ 1000) ઉમેરો. માસિક = રોજનો × 30 × કેમેરા. કેમેરાની અંદરના SD કાર્ડમાં રેકોર્ડિંગ મોબાઇલ ડેટા વાપરતું નથી.'],

