    ['slug' => 'laptop-battery-life-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'battery-medium',
     'en' => 'Laptop Battery Life Calculator', 'gu' => 'લેપટોપ બેટરી લાઇફ કેલ્ક્યુલેટર',
     'de' => 'Estimate how many hours a laptop battery will last from its Wh capacity, battery health and average power use.',
     'dg' => 'બેટરીની Wh ક્ષમતા, બેટરી હેલ્થ અને સરેરાશ પાવર વપરાશ પરથી લેપટોપ બેટરી કેટલા કલાક ચાલશે તે અંદાજો.',
     'in' => [
       ['k' => 'wh', 'en' => 'Battery capacity', 'gu' => 'બેટરી ક્ષમતા', 'v' => 50, 'u' => 'Wh'],
       ['k' => 'health', 'en' => 'Battery health', 'gu' => 'બેટરી હેલ્થ', 'v' => 85, 'u' => '%'],
       ['k' => 'w', 'en' => 'Average power use', 'gu' => 'સરેરાશ પાવર વપરાશ', 'v' => 12, 'u' => 'W', 'opts' => [[7, 'Light – reading, typing (≈7 W)', 'હળવું – વાંચન, ટાઇપિંગ (≈7 W)'], [12, 'Normal – browsing, office (≈12 W)', 'સામાન્ય – બ્રાઉઝિંગ, ઓફિસ (≈12 W)'], [20, 'Video calls, streaming (≈20 W)', 'વીડિયો કોલ, સ્ટ્રીમિંગ (≈20 W)'], [45, 'Gaming, editing (≈45 W)', 'ગેમિંગ, એડિટિંગ (≈45 W)']]],
     ],
     'out' => [
       ['en' => 'Battery backup', 'gu' => 'બેટરી બેકઅપ', 'f' => '((h) => floor(h) + T(" કલાક ", " h ") + round((h - floor(h)) * 60) + T(" મિનિટ", " min"))(v.w ? v.wh * v.health / 100 / v.w : 0)', 'fmt' => 'text', 'big' => 1],
       ['en' => 'Hours (decimal)', 'gu' => 'કલાક (દશાંશ)', 'f' => 'v.w ? v.wh * v.health / 100 / v.w : 0', 'fmt' => 'num', 'u' => 'hrs', 'u_gu' => 'કલાક'],
       ['en' => 'Usable capacity now', 'gu' => 'હાલની વાપરી શકાય તેટલી ક્ષમતા', 'f' => 'v.wh * v.health / 100', 'fmt' => 'num', 'd' => 1, 'u' => 'Wh'],
     ],
     'how_en' => 'Backup hours = battery Wh × health % ÷ average power in watts. If your battery is listed in mAh, Wh = mAh × voltage ÷ 1000 (for example 4,000 mAh × 11.4 V ≈ 45.6 Wh).',
     'how_gu' => 'બેકઅપ કલાક = બેટરી Wh × હેલ્થ % ÷ સરેરાશ વોટ. બેટરી mAh માં લખેલી હોય તો Wh = mAh × વોલ્ટેજ ÷ 1000 (જેમ કે 4,000 mAh × 11.4 V ≈ 45.6 Wh).',
     'faq' => [['How do I check battery health on Windows?', 'Open Command Prompt and run "powercfg /batteryreport". Compare "Full charge capacity" with "Design capacity" — that ratio is the health %.', 'વિન્ડોઝમાં બેટરી હેલ્થ કેવી રીતે જોવી?', 'Command Prompt ખોલી "powercfg /batteryreport" ચલાવો. "Full charge capacity" ને "Design capacity" સાથે સરખાવો — તે ગુણોત્તર હેલ્થ % છે.']]],

    ['slug' => 'ssd-lifespan-tbw-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'hard-drive',
     'en' => 'SSD Lifespan Calculator (TBW)', 'gu' => 'SSD આયુષ્ય કેલ્ક્યુલેટર (TBW)',
     'de' => 'Find how many years an SSD will last from its TBW endurance rating, your daily writes and data already written.',
     'dg' => 'SSD ના TBW રેટિંગ, રોજના લખાતા ડેટા અને અત્યાર સુધી લખાયેલા ડેટા પરથી SSD કેટલા વર્ષ ચાલશે તે શોધો.',
     'in' => [
       ['k' => 'tbw', 'en' => 'SSD endurance rating', 'gu' => 'SSD એન્ડ્યુરન્સ રેટિંગ', 'v' => 600, 'u' => 'TBW'],
       ['k' => 'gb', 'en' => 'Data written per day', 'gu' => 'રોજ લખાતો ડેટા', 'v' => 40, 'u' => 'GB'],
       ['k' => 'used', 'en' => 'Already written (from SMART)', 'gu' => 'અત્યાર સુધી લખાયેલું (SMART માંથી)', 'v' => 10, 'u' => 'TB'],
     ],
     'out' => [
       ['en' => 'Remaining life', 'gu' => 'બાકીનું આયુષ્ય', 'f' => 'v.gb ? max(0, v.tbw - v.used) * 1000 / (v.gb * 365) : 0', 'fmt' => 'num', 'd' => 1, 'u' => 'years', 'u_gu' => 'વર્ષ', 'big' => 1],
       ['en' => 'Total life from new', 'gu' => 'નવાથી કુલ આયુષ્ય', 'f' => 'v.gb ? v.tbw * 1000 / (v.gb * 365) : 0', 'fmt' => 'num', 'd' => 1, 'u' => 'years', 'u_gu' => 'વર્ષ'],
       ['en' => 'Endurance used', 'gu' => 'વપરાયેલી ક્ષમતા', 'f' => 'v.tbw ? min(100, v.used / v.tbw * 100) : 0', 'fmt' => 'pct', 'd' => 1],
     ],
     'how_en' => 'Life in years = (TBW − TB already written) × 1000 ÷ (GB written per day × 365). Normal office PCs write 10–30 GB a day; video editing can write 100 GB or more.',
     'how_gu' => 'વર્ષમાં આયુષ્ય = (TBW − અત્યાર સુધી લખાયેલા TB) × 1000 ÷ (રોજના GB × 365). સામાન્ય ઓફિસ PC રોજ 10–30 GB લખે; વીડિયો એડિટિંગમાં 100 GB કે વધુ.',
     'faq' => [['Will the SSD stop working at TBW?', 'Not suddenly. TBW is the warranty endurance limit; most SSDs keep working beyond it, but keep backups and watch SMART health as you get close. Warranty years also apply, whichever comes first.', 'TBW પૂરું થતાં SSD બંધ થઈ જશે?', 'અચાનક નહીં. TBW વોરંટીની મર્યાદા છે; મોટા ભાગના SSD તેનાથી આગળ ચાલે, પણ નજીક પહોંચો ત્યારે બેકઅપ રાખો અને SMART હેલ્થ જુઓ. વોરંટીના વર્ષ પણ લાગુ પડે, જે પહેલું આવે.']]],

    ['slug' => 'monitor-tv-viewing-distance-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'monitor',
     'en' => 'Monitor & TV Viewing Distance Calculator', 'gu' => 'મોનિટર અને TV જોવાનું અંતર કેલ્ક્યુલેટર',
     'de' => 'Find the ideal viewing distance for a monitor or TV from screen size and resolution, plus the screen width and height.',
     'dg' => 'સ્ક્રીન સાઇઝ અને રિઝોલ્યુશન પરથી મોનિટર કે TV જોવાનું યોગ્ય અંતર અને સ્ક્રીનની પહોળાઈ-ઊંચાઈ શોધો.',
     'in' => [
       ['k' => 'diag', 'en' => 'Screen size (diagonal)', 'gu' => 'સ્ક્રીન સાઇઝ (ત્રાંસી)', 'v' => 27, 'u' => 'inch', 'u_gu' => 'ઇંચ'],
       ['k' => 'px', 'en' => 'Resolution (16:9)', 'gu' => 'રિઝોલ્યુશન (16:9)', 'v' => 2560, 'opts' => [[1366, 'HD (1366 × 768)', 'HD (1366 × 768)'], [1920, 'Full HD (1920 × 1080)', 'ફુલ HD (1920 × 1080)'], [2560, 'QHD (2560 × 1440)', 'QHD (2560 × 1440)'], [3840, '4K (3840 × 2160)', '4K (3840 × 2160)']]],
     ],
     'out' => [
       ['en' => 'Pixels blend from (sharpest distance)', 'gu' => 'પિક્સેલ ન દેખાય તે અંતર', 'f' => 'v.diag ? 3438 / (v.px / (v.diag * 16 / sqrt(337))) * 2.54 : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'cm', 'big' => 1],
       ['en' => 'Immersive distance (40° view)', 'gu' => 'ઇમર્સિવ અંતર (40° દ્રશ્ય)', 'f' => 'v.diag * 16 / sqrt(337) / (2 * tan(rad(20))) * 2.54', 'fmt' => 'num', 'd' => 0, 'u' => 'cm'],
       ['en' => 'Relaxed distance (30° view)', 'gu' => 'આરામદાયક અંતર (30° દ્રશ્ય)', 'f' => 'v.diag * 16 / sqrt(337) / (2 * tan(rad(15))) * 2.54', 'fmt' => 'num', 'd' => 0, 'u' => 'cm'],
       ['en' => 'Screen width × height', 'gu' => 'સ્ક્રીન પહોળાઈ × ઊંચાઈ', 'f' => 'round(v.diag * 16 / sqrt(337) * 2.54, 1) + " × " + round(v.diag * 9 / sqrt(337) * 2.54, 1) + " cm"', 'fmt' => 'text'],
       ['en' => 'Pixel density', 'gu' => 'પિક્સેલ ઘનતા', 'f' => 'v.diag ? v.px / (v.diag * 16 / sqrt(337)) : 0', 'fmt' => 'num', 'd' => 0, 'u' => 'PPI'],
     ],
     'how_en' => 'For 16:9 screens width = diagonal × 16 ÷ √337. PPI = horizontal pixels ÷ width. Pixels blend (1 arc-minute) at 3438 ÷ PPI inches. Viewing angle distances = width ÷ (2 × tan(angle ÷ 2)). Sit between the immersive and relaxed figures; never closer than the pixel-blend distance for sharpness.',
     'how_gu' => '16:9 સ્ક્રીન માટે પહોળાઈ = ત્રાંસી × 16 ÷ √337. PPI = આડા પિક્સેલ ÷ પહોળાઈ. 3438 ÷ PPI ઇંચથી પિક્સેલ ભળી જાય (1 આર્ક-મિનિટ). દ્રશ્ય કોણ અંતર = પહોળાઈ ÷ (2 × tan(કોણ ÷ 2)). ઇમર્સિવ અને આરામદાયક અંતર વચ્ચે બેસો.'],

    ['slug' => 'data-recovery-cost-estimator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'database',
