    ['slug' => 'raid-capacity-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'server',
     'en' => 'RAID Capacity Calculator (RAID 0, 1, 5, 6, 10)', 'gu' => 'RAID ક્ષમતા કેલ્ક્યુલેટર (RAID 0, 1, 5, 6, 10)',
