     'out' => [
       ['en' => 'Usable capacity', 'gu' => 'વાપરી શકાય તેટલી ક્ષમતા', 'f' => 'v.lvl == 0 ? v.n * v.s : v.lvl == 1 ? v.s : v.lvl == 5 ? max(0, v.n - 1) * v.s : v.lvl == 6 ? max(0, v.n - 2) * v.s : floor(v.n / 2) * v.s', 'fmt' => 'num', 'u' => 'TB', 'big' => 1],
       ['en' => 'Raw capacity', 'gu' => 'કુલ કાચી ક્ષમતા', 'f' => 'v.n * v.s', 'fmt' => 'num', 'u' => 'TB'],
       ['en' => 'Space efficiency', 'gu' => 'જગ્યાની એફિશિયન્સી', 'f' => 'v.n * v.s ? (v.lvl == 0 ? v.n * v.s : v.lvl == 1 ? v.s : v.lvl == 5 ? max(0, v.n - 1) * v.s : v.lvl == 6 ? max(0, v.n - 2) * v.s : floor(v.n / 2) * v.s) / (v.n * v.s) * 100 : 0', 'fmt' => 'pct', 'd' => 0],
       ['en' => 'Drive failures survived', 'gu' => 'કેટલી ડ્રાઇવ બગડે તો ચાલે', 'f' => 'v.lvl == 0 ? T("0 – એક ડ્રાઇવ બગડે તો બધો ડેટા જાય", "0 – one failure loses all data") : v.lvl == 1 ? (v.n - 1) + T(" ડ્રાઇવ", " drive(s)") : v.lvl == 5 ? T("1 ડ્રાઇવ", "1 drive") : v.lvl == 6 ? T("કોઈપણ 2 ડ્રાઇવ", "Any 2 drives") : T("દરેક મિરર જોડીમાંથી 1", "1 per mirror pair")', 'fmt' => 'text'],
