     'how_gu' => 'k મા વર્ષનો ડેટા = આજનો ડેટા × (1 + વધારો)^(k−1). વાર્ષિક ખર્ચ = TB માં ડેટા × TB દીઠ ભાવ × 12. કુલ = પ્રથમ વર્ષનો ખર્ચ × ((1 + g)^વર્ષ − 1) ÷ g (ભૌમિતિક શ્રેણી; વધારો 0 હોય તો સાદો સરવાળો).'],

    ['slug' => 'computer-depreciation-calculator-wdv', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'trending-down',
     'en' => 'Computer & Laptop Depreciation Calculator (WDV)', 'gu' => 'કમ્પ્યુટર અને લેપટોપ ઘસારા કેલ્ક્યુલેટર (WDV)',
     'de' => 'Calculate written-down value and depreciation of computers, laptops and printers for business books with your rate and half-year rule.',
     'dg' => 'તમારા દર અને અડધા વર્ષના નિયમ સાથે વ્યવસાયના ચોપડા માટે કમ્પ્યુટર, લેપટોપ અને પ્રિન્ટરનો ઘસારો અને WDV કિંમત ગણો.',
     'in' => [
       ['k' => 'cost', 'en' => 'Purchase cost', 'gu' => 'ખરીદ કિંમત', 'v' => 60000, 'u' => '₹'],
       ['k' => 'rate', 'en' => 'Depreciation rate (WDV)', 'gu' => 'ઘસારા દર (WDV)', 'v' => 40, 'u' => '%'],
       ['k' => 'years', 'en' => 'Years', 'gu' => 'વર્ષ', 'v' => 3],
       ['k' => 'half', 'en' => 'Used in first year', 'gu' => 'પ્રથમ વર્ષે વપરાશ', 'v' => 1, 'opts' => [[1, '180 days or more (full rate)', '180 દિવસ કે વધુ (પૂરો દર)'], [0.5, 'Less than 180 days (half rate)', '180 દિવસથી ઓછો (અડધો દર)']]],
     ],
     'out' => [
       ['en' => 'Book value after the years', 'gu' => 'વર્ષો પછી ચોપડા કિંમત', 'f' => 'v.years >= 1 ? v.cost * (1 - v.rate / 100 * v.half) * pow(1 - v.rate / 100, v.years - 1) : v.cost', 'fmt' => 'inr', 'big' => 1],
       ['en' => 'First year depreciation', 'gu' => 'પ્રથમ વર્ષનો ઘસારો', 'f' => 'v.cost * v.rate / 100 * v.half', 'fmt' => 'inr'],
       ['en' => 'Total depreciation', 'gu' => 'કુલ ઘસારો', 'f' => 'v.cost - (v.years >= 1 ? v.cost * (1 - v.rate / 100 * v.half) * pow(1 - v.rate / 100, v.years - 1) : v.cost)', 'fmt' => 'inr'],
       ['en' => 'Depreciation in last year', 'gu' => 'છેલ્લા વર્ષનો ઘસારો', 'f' => 'v.years > 1 ? v.cost * (1 - v.rate / 100 * v.half) * pow(1 - v.rate / 100, v.years - 2) * v.rate / 100 : v.cost * v.rate / 100 * v.half', 'fmt' => 'inr'],
     ],
     'how_en' => 'Written-down value method: year 1 depreciation = cost × rate × (½ if used under 180 days). Each later year = opening value × rate. Value after n years = cost × (1 − rate × half) × (1 − rate)^(n−1). Check the current rate for computers with your CA.',
     'how_gu' => 'WDV પદ્ધતિ: પ્રથમ વર્ષનો ઘસારો = કિંમત × દર × (180 દિવસથી ઓછો વપરાશ હોય તો ½). પછીના દરેક વર્ષે = શરૂઆતની કિંમત × દર. n વર્ષ પછી કિંમત = કિંમત × (1 − દર × અડધું) × (1 − દર)^(n−1). કમ્પ્યુટર માટેનો હાલનો દર તમારા CA પાસે તપાસો.'],

