    ['slug' => 'office-internet-bandwidth-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'router',
     'en' => 'Office Internet Speed Requirement Calculator', 'gu' => 'ઓફિસ માટે ઇન્ટરનેટ સ્પીડ જરૂરિયાત કેલ્ક્યુલેટર',
     'de' => 'Estimate the broadband speed an office, school or shop needs from users browsing, on video calls, CCTV viewing and cloud work.',
     'dg' => 'બ્રાઉઝિંગ, વીડિયો કોલ, CCTV જોવા અને ક્લાઉડ કામ કરતા યુઝર પરથી ઓફિસ, સ્કૂલ કે દુકાનને કેટલી બ્રોડબેન્ડ સ્પીડ જોઈએ તે અંદાજો.',
     'in' => [
       ['k' => 'bu', 'en' => 'Users browsing / billing software', 'gu' => 'બ્રાઉઝિંગ / બિલિંગ સોફ્ટવેર યુઝર', 'v' => 15],
       ['k' => 'bm', 'en' => 'Speed per browsing user', 'gu' => 'બ્રાઉઝિંગ યુઝર દીઠ સ્પીડ', 'v' => 1, 'u' => 'Mbps'],
       ['k' => 'vu', 'en' => 'Users on HD video calls', 'gu' => 'HD વીડિયો કોલ પર યુઝર', 'v' => 5],
       ['k' => 'vm', 'en' => 'Speed per video call', 'gu' => 'વીડિયો કોલ દીઠ સ્પીડ', 'v' => 3, 'u' => 'Mbps'],
       ['k' => 'other', 'en' => 'CCTV remote view, cloud sync etc.', 'gu' => 'CCTV રિમોટ વ્યૂ, ક્લાઉડ સિંક વગેરે', 'v' => 8, 'u' => 'Mbps'],
       ['k' => 'conc', 'en' => 'Users active at the same time', 'gu' => 'એક સાથે સક્રિય યુઝર', 'v' => 70, 'u' => '%'],
       ['k' => 'head', 'en' => 'Headroom', 'gu' => 'વધારાની જગ્યા', 'v' => 25, 'u' => '%'],
     ],
     'out' => [
       ['en' => 'Recommended plan speed', 'gu' => 'ભલામણ કરેલ પ્લાન સ્પીડ', 'f' => '((m) => m <= 30 ? 30 : m <= 50 ? 50 : m <= 100 ? 100 : m <= 150 ? 150 : m <= 200 ? 200 : m <= 300 ? 300 : m <= 500 ? 500 : m <= 1000 ? 1000 : ceil(m / 500) * 500)(((v.bu * v.bm + v.vu * v.vm) * v.conc / 100 + v.other) * (1 + v.head / 100))', 'fmt' => 'int', 'u' => 'Mbps', 'big' => 1],
       ['en' => 'Calculated need', 'gu' => 'ગણેલી જરૂરિયાત', 'f' => '((v.bu * v.bm + v.vu * v.vm) * v.conc / 100 + v.other) * (1 + v.head / 100)', 'fmt' => 'num', 'd' => 1, 'u' => 'Mbps'],
       ['en' => 'Upload speed needed (video calls + CCTV)', 'gu' => 'જરૂરી અપલોડ સ્પીડ (વીડિયો કોલ + CCTV)', 'f' => '(v.vu * v.vm * v.conc / 100 + v.other) * (1 + v.head / 100)', 'fmt' => 'num', 'd' => 1, 'u' => 'Mbps'],
     ],
     'how_en' => 'Need = (browsing users × Mbps + video-call users × Mbps) × share active together + always-on traffic (CCTV, sync), plus headroom %. Video calls and CCTV remote viewing also need similar upload speed, so prefer symmetric fibre plans.',
     'how_gu' => 'જરૂરિયાત = (બ્રાઉઝિંગ યુઝર × Mbps + વીડિયો કોલ યુઝર × Mbps) × એક સાથે સક્રિય ભાગ + સતત ચાલતો ટ્રાફિક (CCTV, સિંક), ઉપરાંત વધારાની જગ્યા %. વીડિયો કોલ અને CCTV રિમોટ વ્યૂ માટે અપલોડ સ્પીડ પણ એટલી જોઈએ, તેથી સરખી અપલોડ-ડાઉનલોડવાળા ફાઇબર પ્લાન સારા.'],

    ['slug' => 'computer-amc-cost-calculator', 'cat' => 'computer', 'type' => 'calc', 'icon' => 'calendar-check',
     'en' => 'Computer AMC Cost Calculator', 'gu' => 'કમ્પ્યુટર AMC ખર્ચ કેલ્ક્યુલેટર',
     'de' => 'Price a yearly computer AMC for an office with desktops, laptops, printers and servers, a volume discount and GST.',
     'dg' => 'ડેસ્કટોપ, લેપટોપ, પ્રિન્ટર અને સર્વરવાળી ઓફિસ માટે વોલ્યુમ ડિસ્કાઉન્ટ અને GST સાથે વાર્ષિક કમ્પ્યુટર AMC નો ભાવ નક્કી કરો.',
     'in' => [
       ['k' => 'pc', 'en' => 'Desktops', 'gu' => 'ડેસ્કટોપ', 'v' => 10],
       ['k' => 'pcr', 'en' => 'Rate per desktop per year', 'gu' => 'ડેસ્કટોપ દીઠ વાર્ષિક દર', 'v' => 1200, 'u' => '₹'],
       ['k' => 'lp', 'en' => 'Laptops', 'gu' => 'લેપટોપ', 'v' => 3],
       ['k' => 'lpr', 'en' => 'Rate per laptop per year', 'gu' => 'લેપટોપ દીઠ વાર્ષિક દર', 'v' => 1500, 'u' => '₹'],
       ['k' => 'pr', 'en' => 'Printers', 'gu' => 'પ્રિન્ટર', 'v' => 2],
       ['k' => 'prr', 'en' => 'Rate per printer per year', 'gu' => 'પ્રિન્ટર દીઠ વાર્ષિક દર', 'v' => 800, 'u' => '₹'],
       ['k' => 'sv', 'en' => 'Servers / NAS', 'gu' => 'સર્વર / NAS', 'v' => 0],
       ['k' => 'svr', 'en' => 'Rate per server per year', 'gu' => 'સર્વર દીઠ વાર્ષિક દર', 'v' => 6000, 'u' => '₹'],
       ['k' => 'disc', 'en' => 'Volume discount', 'gu' => 'વોલ્યુમ ડિસ્કાઉન્ટ', 'v' => 10, 'u' => '%'],
       ['k' => 'gst', 'en' => 'GST', 'gu' => 'GST', 'v' => 18, 'u' => '%'],
     ],
     'out' => [
       ['en' => 'Yearly AMC (with GST)', 'gu' => 'વાર્ષિક AMC (GST સાથે)', 'f' => '(v.pc * v.pcr + v.lp * v.lpr + v.pr * v.prr + v.sv * v.svr) * (1 - v.disc / 100) * (1 + v.gst / 100)', 'fmt' => 'inr', 'big' => 1],
       ['en' => 'Before discount', 'gu' => 'ડિસ્કાઉન્ટ પહેલાં', 'f' => 'v.pc * v.pcr + v.lp * v.lpr + v.pr * v.prr + v.sv * v.svr', 'fmt' => 'inr'],
       ['en' => 'After discount (before GST)', 'gu' => 'ડિસ્કાઉન્ટ પછી (GST પહેલાં)', 'f' => '(v.pc * v.pcr + v.lp * v.lpr + v.pr * v.prr + v.sv * v.svr) * (1 - v.disc / 100)', 'fmt' => 'inr'],
       ['en' => 'Per month', 'gu' => 'માસિક', 'f' => '(v.pc * v.pcr + v.lp * v.lpr + v.pr * v.prr + v.sv * v.svr) * (1 - v.disc / 100) * (1 + v.gst / 100) / 12', 'fmt' => 'inr'],
       ['en' => 'Average per device', 'gu' => 'ઉપકરણ દીઠ સરેરાશ', 'f' => '(v.pc + v.lp + v.pr + v.sv) ? (v.pc * v.pcr + v.lp * v.lpr + v.pr * v.prr + v.sv * v.svr) * (1 - v.disc / 100) * (1 + v.gst / 100) / (v.pc + v.lp + v.pr + v.sv) : 0', 'fmt' => 'inr'],
     ],
     'how_en' => 'AMC = Σ (devices × yearly rate) − volume discount %, then GST is added. Monthly = yearly ÷ 12. Mention in the contract whether parts are included (comprehensive) or only labour (non-comprehensive).',
     'how_gu' => 'AMC = Σ (ઉપકરણ × વાર્ષિક દર) − વોલ્યુમ ડિસ્કાઉન્ટ %, પછી GST ઉમેરાય. માસિક = વાર્ષિક ÷ 12. કરારમાં પાર્ટ્સ સામેલ છે (કોમ્પ્રિહેન્સિવ) કે ફક્ત મજૂરી (નોન-કોમ્પ્રિહેન્સિવ) તે લખો.'],

